- How would you extend to support deletion or word counts?

## Why This Is Asked

Tests understanding of stability and permutation-based sorting, ensuring candidates can separate data from its keys and reason about time/space trade-offs.

## Key Concepts

- Stable sort
- Permutations
- Time/space complexity
- Merge-based sorting on indices

## Code Example

```javascript
function stableSortIndicesByValue(A){
  const idx = Array.from({length: A.length}, (_, i) => i);
  function merge(left, right){
    const res = [];
    let i = 0, j = 0;
    while (i < left.length && j < right.length){
      if (A[left[i]] <= A[right[j]]) res.push(left[i++]);
      else res.push(right[j++]);
    }
    while (i < left.length) res.push(left[i++]);
    while (j < right.length) res.push(right[j++]);
    return res;
  }
  function sort(arr){
    if (arr.length <= 1) return arr;
    const m = Math.floor(arr.length / 2);
    const L = sort(arr.slice(0, m));
    const R = sort(arr.slice(m));
    return merge(L, R);
  }
  const P = sort(idx);
  return { P, sorted: P.map(i => A[i]) };
}
```

## Why This Is Asked
Tests ability to frame a sign-assignment problem as a DP and implement both memoization and tabulation, a common interview pattern.

## Key Concepts
- DP state reduction to subset sum
- Space optimization with a 1D array
- Memoization vs bottom-up trade-offs

## Code Example
```javascript
// Tabulation and Memo versions
function countTargetSumTab(nums, S) {
  const total = nums.reduce((a,b)=>a+b,0);
  if (Math.abs(S) > total || (total+S)%2 !== 0) return 0;
  const target = (total+S)/2;
  const dp = Array(target+1).fill(0);
  dp[0] = 1;
  for (const n of nums) {
    for (let t = target; t >= n; t--) dp[t] += dp[t-n];
  }
  return dp[target];
}

function countTargetSumMemo(nums, S) {
  const total = nums.reduce((a,b)=>a+b,0);
  if (Math.abs(S) > total || (total+S)%2 !== 0) return 0;
  const target = (total+S)/2;
  const memo = new Map();
  function dfs(i, sum){
    if (sum > target) return 0;
    if (i === nums.length) return sum === target ? 1 : 0;
    const key = i+':'+sum;
    if (memo.has(key)) return memo.get(key);
    const res = dfs(i+1, sum+nums[i]) + dfs(i+1, sum);
    memo.set(key, res);
    return res;
  }
  return dfs(0,0);
}
```

